SELECT b.bear_bucket, COUNT(*) AS n, SUM(b.realized_pnl<0) AS losses, ROUND(SUM(b.realized_pnl),4) AS pnl_usdt, ROUND(AVG(b.ret_pct),4) AS avg_ret_pct, ROUND(AVG(b.held_s),0) AS avg_hold_s FROM (SELECT p.id, p.realized_pnl, (p.exit_price-p.entry_price)/p.entry_price*100 AS ret_pct, UNIX_TIMESTAMP(p.closed_at)-UNIX_TIMESTAMP(p.opened_at) AS held_s, CASE WHEN x.bear15 >= 10 THEN 'A:>=10' WHEN x.bear15 >= 5 THEN 'B:5-9' WHEN x.bear15 >= 1 THEN 'C:1-4' ELSE 'D:0' END AS bear_bucket FROM crypto_ai.paper_position p JOIN (SELECT p2.id AS pid, (SELECT COUNT(*) FROM crypto_ai.trade_signal s WHERE s.symbol=es.symbol AND s.interval_code='1m' AND s.decision IN ('SELL','STRONG_SELL') AND s.generated_at < es.generated_at AND s.generated_at >= FROM_UNIXTIME(UNIX_TIMESTAMP(es.generated_at)-900)) AS bear15 FROM crypto_ai.paper_position p2 JOIN crypto_ai.trade_signal es ON es.id=p2.signal_id WHERE p2.status='CLOSED' AND p2.closed_at >= FROM_UNIXTIME(UNIX_TIMESTAMP()-14*86400)) x ON x.pid=p.id) b GROUP BY b.bear_bucket ORDER BY b.bear_bucket LIMIT 10;